<script setup lang="ts">
import {computed,ref} from 'vue'
import {api} from '../api'
import {usePolling} from '../usePolling'
import {number,price,time,statusName} from '../format'
import {paperDirection} from '../paper'
import type {PaperPosition,PaperTrade} from '../paper'
import type {MarketView} from '../types'
const props=defineProps<{positions?:PaperPosition[];trades?:PaperTrade[]}>()
type Sample={positionId:string;capturedAt:string;event:string;version:string;position:PaperPosition;market:MarketView|null;dataFresh:boolean;markPnl:number|null;accountEquity:number|null;executions:PaperTrade[]}
type History={total:number;records:Sample[];nextBefore:number|null;meaning:string}
const history=ref<History|null>(null);const filter=ref('');const before=ref<number|null>(null);const actionError=ref('');let request=0
async function load(signal?:AbortSignal){const id=++request;const q=new URLSearchParams({limit:'200'});if(filter.value)q.set('positionId',filter.value);if(before.value!==null)q.set('before',String(before.value));const h=await api<History>(`/api/paper/holding-history?${q}`,{signal});if(id===request)history.value=h}
const {error}=usePolling(load,30000)
async function change(older=false){actionError.value='';before.value=older?history.value?.nextBefore??null:null;try{await load()}catch(e){actionError.value=e instanceof Error?e.message:String(e)}}
const choices=computed(()=>{const map=new Map<string,string>();for(const p of props.positions??[])map.set(p.id,`${p.symbol} · ${paperDirection(p.direction)} · ${time(p.openedAt)}`);for(const t of props.trades??[])map.set(t.positionId??t.id,`${t.symbol} · ${paperDirection(t.direction)} · ${time(t.openedAt)}`);for(const h of history.value?.records??[])map.set(h.positionId,`${h.position.symbol} · ${paperDirection(h.position.direction)} · ${time(h.position.openedAt)}`);return [...map].map(([id,label])=>({id,label}))})
</script>
<template><section class="detail"><h2>持仓过程留档 · 约每分钟与关键动作</h2><p>风险检查约5秒一次；此处定期保存约每分钟的本地上下文，开仓、减仓、平仓额外留档。不是逐笔盘口或每5秒行情回放，不新增外部请求。此前没有持仓快照的时段不补造。</p><p v-if="error||actionError" role="alert" class="radar-notice">{{actionError||error}}</p><label>选择持仓 <select v-model="filter" @change="change()"><option value="">所有持仓最近200条</option><option v-for="c in choices" :key="c.id" :value="c.id">{{c.label}}</option></select></label><button class="text-button" @click="change()">最新记录</button><button class="text-button" :disabled="!filter||!history?.records.length" @click="change(true)">更早记录</button><p>本地累计 {{history?.total??0}} 条；本页 {{history?.records.length??0}} 条。平仓后记录仍保留；按单笔持仓可以翻页。</p>
<p v-if="history&&!history.records.length" class="empty">当前没有持仓过程快照。无持仓不会产生记录，不用测试成交填充正式账户。</p>
<details v-for="h in history?.records" :key="`${h.positionId}:${h.capturedAt}`"><summary>{{time(h.capturedAt)}} · {{h.position.symbol}} · {{paperDirection(h.position.direction)}} · {{h.event}} · {{h.dataFresh?'报价新鲜':'报价失鲜 / 缺失'}}</summary><p>标记浮盈亏 {{number(h.markPnl,3)}} USDT，账户净值 {{number(h.accountEquity,2)}}；数量 {{number(h.position.quantity,6)}}，剩余保证金 {{number(h.position.remainingMargin,2)}}，开仓价 {{price(h.position.entryPrice)}}。退出上下文里的数量是退出前，最终数量及结算以本次执行记录为准。</p><p>当时止损 {{price(h.position.stopPrice)}}；两级目标 {{price(h.position.takePrice)}} / {{price(h.position.target2)}}；第一批 {{h.position.firstTaken?'已减':'未减'}}，第二批 {{h.position.secondTaken?'已减':'未减'}}。</p>
<template v-if="h.market"><p>报价 {{price(h.market.price)}} · 标记价 {{price(h.market.markPrice)}} · 来源 {{time(h.market.priceSourceTime)}} · 接收 {{time(h.market.priceReceivedTime)}}。新鲜只指价格/标记，其他指标分别检查自己的时间和状态。</p><p>OI数量 {{number(h.market.features.derivatives.openInterestQuantity.value,2)}} · {{statusName(h.market.features.derivatives.openInterestQuantity.status)}} · {{time(h.market.features.derivatives.openInterestQuantity.sourceTime)}}；结构 {{h.market.features.derivatives.priceOiStructure}}。</p><p>24h成交额 {{number(h.market.volume24h,0)}}；24h涨跌 {{number(h.market.exchangeReturn24h,2)}}%；主动买入占比 {{number(h.market.features.derivatives.takerBuyShare.value,3)}} · {{statusName(h.market.features.derivatives.takerBuyShare.status)}}；整体多头账户占比 {{number(h.market.features.derivatives.globalLongShare.value,3)}} · {{statusName(h.market.features.derivatives.globalLongShare.status)}}。</p><p>资金费报价 {{number(h.market.fundingRate==null?null:h.market.fundingRate*100,5)}}% · 来源 {{time(h.market.fundingSourceTime)}}；账本尚未分摊的资金费成本假设 {{number(h.position.fundingCost,4)}} USDT，两者不是同一口径。</p><p>资产身份 {{h.market.features.capital?.trustedIdentity?'已核对':'Unknown / 未核对'}}；持币地址数 {{number(h.market.features.onChain?.holderCount.value,0)}} · 来源 {{time(h.market.features.onChain?.holderCount.sourceTime)}}。缺失不等于安全，也不等于没有转账。</p></template>
<p v-for="e in h.executions" :key="e.id">本次结算：{{e.reason}} · 数量 {{number(e.quantity,6)}} · 成交假设 {{price(e.exitPrice)}} · 净额 {{number(e.netPnl,4)}} USDT。</p><small>{{h.version}} · {{history?.meaning}}</small></details></section></template>
<style scoped>select{max-width:min(100%,520px);padding:8px;margin:8px;background:#10171e;color:#d6e6ed;border:1px solid #30414b;border-radius:5px}details{padding:14px 0;border-top:1px solid #26343c}summary{cursor:pointer}small{overflow-wrap:anywhere}</style>
